const e={title:"TripReel - Ingyenes Utazási Animációs Alkalmazás: Alakítsa Át a Fényképeket Szép Videóká",description:"Hozzon létre lenyűgöző utazási videókat animált térképekkel és repülési útvonalakkal. Ingyenes utazási animációs alkalmazás 3D földgömb útvonal-leképezéssel. Alakítsa át fényképeit gyönyörű utazási videóká automatikusan. Adatvédelem első, offline működik.",keywords:"utazási animációs alkalmazás, utazási térkép animációs alkalmazás, utazási útvonal animációs alkalmazás, repülési animációs alkalmazás, utazási videó készítő, automatikus utazási videó, animált utazási térkép, repülési útvonal animáció, utazási animáció, földgömb animáció, utazási visszatekintő videó, fénykép videóvá, utazási kiemelések, ingyenes utazási alkalmazás, offline videó készítő, adatvédelmi utazási alkalmazás, kamera tekercs videó"},a={logoAlt:"TripReel logó",appName:"TripReel",howItWorks:"Hogyan működik",video:"Videó",features:"Funkciók",theApp:"Az alkalmazás"},t={badge:"Alakítsd fotókat utazási történetekké",title1:"A fotótárad,",title2:"Teljes pompájában",description:"A TripReel automatikusan gyönyörű utazási videókat készít a fotóid helyei alapján. Nézd, ahogy utazásaid életre kelnek lenyűgöző animált útvonaltérképekkel és repülési útvonalakkal egy 3D földgömbön, miközben adataid biztonságban és védve maradnak.",secure:"100% biztonságos",worksOffline:"Offline is működik",globeAlt:"TripReel földgömb animáció"},s={title:"Hogyan működik",subtitle:"Három egyszerű lépés a tökéletes utazási videó elkészítéséhez",step1:{title:"Fotóhozzáférés engedélyezése",description:"Add meg a TripReel számára a hozzáférést a fotótáradhoz. Az alkalmazás csak a helyadatokat olvassa, semmi mást."},step2:{title:"Automatikus utazásfelismerés",description:"A TripReel elemzi a helyadatokat, és intelligensen megtalálja utazásaidat a dátumok és helyek alapján."},step3:{title:"Videó készítése",description:"Nézd, ahogy utazásod kibontakozik egy gyönyörű földgömb animáción, készen a közösségi médiában való megosztásra."}},l={title:"Nézd a varázslatot",subtitle:"Nézd meg, hogyan alakítja a TripReel a fotótáradat lenyűgöző utazási videókká",caption:"Így fog kinézni a végső utazási videód"},i={title:"Minden, amire szükséged van",subtitle:"Hatékony funkciók modern utazóknak tervezve",twoTap:{title:"Két érintéssel videó",description:"Készíts lenyűgöző utazási összefoglaló videókat a fotótáradból mindössze két érintéssel. Szerkesztés nem szükséges."},smartTrip:{title:"Intelligens utazásfelismerés",description:"Automatikusan megtalálja és csoportosítja utazásaidat a fotóid dátumainak és helyadatainak elemzésével."},globe:{title:"Gyönyörű földgömb animáció",description:"Nézd, ahogy utazásod életre kel egy lenyűgöző 3D földgömbön, amely animált utazási útvonalaidat és repülési útvonalaidat mutatja be szerte a világon."},privacy:{title:"Adatvédelem az első",description:"Minden feldolgozás az eszközödön történik. A fotóid soha nem hagyják el a telefonodat. Repülőgép módban is működik."},customStyles:{title:"Egyedi stílusok",description:"Válassz több földgömb stílus és testreszabás közül, hogy illeszkedjen esztétikádhoz, és tedd minden videót egyedivé."},manualControl:{title:"Kézi vezérlés",description:"Manuálisan is hozzáadhatsz teljesen új utazásokat, ha a helymeghatározási szolgáltatások nem voltak engedélyezve az eszközödön."}},n={title:"Kreatív videó ötletek",subtitle:"Szerezz inspirációt azzal, amit a TripReel segítségével létrehozhatsz. A gyors hétvégi kiruccanásoktól az egész éves kalandokig, készíts lenyűgöző utazási videókat minden útra.",description:"Akár utazási térkép animációt készítesz, repülési útvonalat dokumentálsz, vagy év végi utazási összefoglalót készítesz, a TripReel egyszerűvé teszi emlékeid megosztható videókká alakítását.",ideas:{yearRecap:{title:"2025 utazási összefoglaló",description:"Készítsd el automatikusan a 2025-ös éves utazási összefoglaló videódat"},europeRoadTrip:{title:"Európai autós túra",description:"Mutasd be európai kalandodat animált útvonaltérképekkel"},southeastAsia:{title:"Délkelet-ázsiai utazás",description:"Jelenítsd meg hátizsákos utadat több országon keresztül"},japanRail:{title:"Japán vasúti utazás",description:"Készíts térkép videókat a japán vonatútvonalaidról"},crossCountry:{title:"Keresztül az USA-n",description:"Alakítsd amerikai autós túrádat epikus útvonal videóvá"},islandHopping:{title:"Szigetről szigetre",description:"Mutasd meg szigetről szigetre utazásaidat lenyűgöző 3D animációkkal"},worldTour:{title:"Világkörüli túra montázs",description:"Több utazás egy csodálatos globális utazási videóban"},travelPlans:{title:"2026 utazási tervek",description:"Jelenítsd meg és tervezd meg izgalmas utazási kalandjaidat 2026-ra"},lifetimeTravel:{title:"Életen át tartó utazási történet",description:"Készíts egy videót, amely bemutatja életedben tett összes utazásod"},regionalExplorer:{title:"Regionális felfedező",description:"Térképezd fel kalandjaidat államokon, tartományokon és régiókon keresztül"},festivalCircuit:{title:"Fesztivál kör",description:"Térképezd fel zenei fesztivál és esemény utazásodat"},bikeRoutes:{title:"Városi kiruccanásaim",description:"Mutasd be minden városi kiruccanásodat"}}},o={title:"Az alkalmazás",subtitle:"Már elérhető az App Store-ban",alt1:"Automatikus utazási videók - Készíts lenyűgöző videókat másodpercek alatt",alt2:"Fotó helymeghatározás - A fotóid metaadatait használja",alt3:"Utazásfelismerés - Automatikusan csoportosítja utazásaidat",alt4:"Gyönyörű földgömb videók - Utazásod földgömb animációja",alt5:"Egyedi stílusok - Szabd személyre utazási videóidat"},z={comingSoon:"Hamarosan",androidTitle:"Az Android alkalmazás hamarosan!",androidMessage:'Az Android verzió még nem érhető el, de hamarosan lesz. Írj nekem a <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> címre, és értesítelek, amikor készen van!',gotIt:"Rendben!"},k={title:"Gyakran ismételt kérdések",subtitle:"Minden, amit a TripReel-ről tudnod kell",q1:{question:"Tényleg használhatom az alkalmazást teljesen repülőgép módban?",answer:"Igen! Prémium felhasználók számára az alkalmazás teljesen offline használható repülőgép módban, korlátozások nélkül. Nem prémium felhasználók számára egyes funkciók hirdetés-támogatottak, amelyek átmenetileg internet engedélyezést igényelhetnek, de prémium felhasználóknak nincsenek hirdetések, és az alkalmazás teljesen használható repülőgép módban."},q2:{question:"Prémiumra frissítettem, hogyan távolíthatom el a vízjelet?",answer:"Sokan kérdezik, hogy melyik alkalmazást használták ezeknek a videóknak a létrehozására, ezért prémiumra frissítés után lehetőséged van hozzáadni a vízjel kisebb verzióját (csak az alkalmazás nevével) vagy teljesen eltávolítani, ha szeretnéd."},q3:{question:"Biztonságosak és privátak a fotóadataim?",answer:"Természetesen! A TripReel csak helyadatokat olvas a fotóidból - soha nem férünk hozzá, nem tároljuk vagy továbbítjuk a tényleges fotótartalmat. Minden feldolgozás helyileg történik az eszközödön, és semmilyen adat nem hagyja el a telefonodat. Ezt repülőgép módban történő használattal ellenőrizheted - tökéletesen működik offline!"},q4:{question:"Mi van, ha a fotóimnak nincs helyadatuk?",answer:"Semmi gond! Ha a helymeghatározási szolgáltatások nem voltak engedélyezve, amikor fotóztál, manuálisan létrehozhatsz utazásokat és magad adhatod hozzá a helyeket. Az alkalmazás teljes kontrollt ad neked utazási idővonaladnak testreszabásához."},q5:{question:"Hogyan észleli az alkalmazás automatikusan az utazásaimat?",answer:"A TripReel elemzi a fotóid helyadatait és időbélyegeit, hogy intelligensen azonosítsa, mikor és hová utaztál. Közeli helyeket és dátumokat csoportosít, hogy automatikusan felismerje utazásaidat manuális munka nélkül."},q6:{question:"Testreszabhatom a videóim megjelenését?",answer:"Igen! Választhatsz több földgömb stílus közül, és testreszabhatod animált utazási videóid különböző aspektusait, hogy illeszkedjenek személyes esztétikádhoz. Prémium felhasználók hozzáférnek további útvonal animáció stílusokhoz, térkép témákhoz és repülési útvonal opciókhoz."},q7:{question:"Létre kell hoznom egy fiókot?",answer:"Nincs szükség fiókra! A TripReel a letöltés után azonnal működik. Nincs regisztráció, nincs bejelentkezés, és nincs szükség személyes információkra. Csak töltsd le az alkalmazást, és kezdd el azonnal létrehozni utazási videóidat."},q8:{question:"Miért hiányzik egy hely az utazásomból?",answer:"Az alkalmazás csak elérhető adatokkal tud dolgozni, szóval először is szükséged van legalább néhány fotóra azon a helyen. Másodszor, meg kell győződnöd róla, hogy engedélyezve voltak a helyadatok, amikor ott voltál. Harmadszor, néha a gyenge GPS vétel rossz helyadatokat okozhat. Ha mindezt kizártad, és a helyed továbbra sem jelenik meg, manuálisan hozzáadhatod azt a helyet a Trips Overview > Edit gombból. Kérlek, használd a Contact-ot is a probléma jelentésére."},q9:{question:"Hol oszthatom meg a csodálatos videómat?",answer:"Természetesen megoszthatod az összes közösségi platformon is. A platformhoz való jobb illeszkedés érdekében az alkalmazás különböző képarányokat tesz lehetővé a videóidhoz."},q10:{question:"Hol jelenthetek be egy hibát?",answer:"Csak lépj velem kapcsolatba közvetlenül a marian@qod.ee címen, röviden elmagyarázva, hogy mi a probléma."}},r={title:"Email támogatás",description:"Ha bármilyen visszajelzésed van, vagy bármilyen problémába ütközöl, kérlek, bátran lépj velem kapcsolatba közvetlenül ezen az e-mail címen, és személyesen elolvasom és kezelni fogom kérésedet a lehető leggyorsabban. Köszönöm, hogy használod az alkalmazást!",close:"Bezárás"},d={default:{title:"🍪 Sütik",message:"Sütiket használunk a TripReel oldalon az élményed fokozásához. Nem gyűjtünk személyes adatokat.",accept:"Elfogadás",decline:"Elutasítás",details:"Részletek"},theme:{title:"🍪 Sütik",message:"🌙 A téma beállításod mentéséhez el kell fogadnod az alapvető sütiket a TripReel oldalon. Nélkülük a téma választásod nem menthető.",accept:"Elfogadás",decline:"Elutasítás",details:"Részletek"}},m={privacy:"Alkalmazás adatvédelmi irányelvek",cookies:"Weboldal süti irányelvek",contact:"Kapcsolat",cookiePreferences:"Süti beállítások",madeWith:"Készült",forTravelers:"világszerte utazóknak",copyright:"© {{year}} TripReel."},g={title:"Készen állsz megosztani utazásodat?",description:"Töltsd le ma a TripReel-t, és alakítsd fotótáradat gyönyörű utazási videókká animált térképekkel és útvonalakkal. Kalandjaid megérdemlik, hogy megünnepeld őket.",features:"Ingyenesen letölthető • Gyors és kényelmes • Garantált adatvédelem"},u={meta:e,header:a,hero:t,howItWorks:s,videoSection:l,features:i,videoIdeas:n,screenshots:o,appStore:z,faq:k,contact:r,cookieBanner:d,footer:m,cta:g};export{z as appStore,r as contact,d as cookieBanner,g as cta,u as default,k as faq,i as features,m as footer,a as header,t as hero,s as howItWorks,e as meta,o as screenshots,n as videoIdeas,l as videoSection};
